import React, { useEffect, useState, useRef } from 'react';
import { Helmet } from 'react-helmet-async';

/**
 * ModernHelmet - A modern replacement for react-helmet-async
 * 
 * This component wraps the Helmet component and implements its own side effect handling
 * to avoid using deprecated lifecycle methods.
 * 
 * @param {Object} props - The props to pass to the Helmet component
 * @returns {JSX.Element} - The wrapped Helmet component
 */
const ModernHelmet = (props) => {
  const [isClient, setIsClient] = useState(false);
  const instanceRef = useRef(null);
  
  // Use useEffect instead of componentDidMount
  useEffect(() => {
    setIsClient(true);
    
    // This simulates what SideEffect does but with hooks
    return () => {
      // Cleanup on unmount
      if (instanceRef.current) {
        // Any cleanup needed
      }
    };
  }, []);
  
  // Only render on client side to avoid SSR issues
  if (!isClient) {
    return null;
  }
  
  return <Helmet {...props} ref={instanceRef} />;
};

export default ModernHelmet;
